			function setContentCrud(psType) {
			    var vcGrpCont = app.lookup("grpCont");
			    
			    if (psType == "READ") {
			        
			        util.Control.setReadOnly(app, true, "grpBoardDtl");
			        
			        // editor 숨김처리 및 html 스니펫 출력
			        vcGrpCont.getLayout().setRowVisible(0, true);
			        vcGrpCont.getLayout().setRowVisible(1, false);
			        
			        app.lookup("grpBoardDtl").getLayout().setRowVisible(1, false);
			        app.lookup("grpBoardDtl").getLayout().setRowVisible(2, false);
			        
			        util.Control.setVisible(app, false, ["btnRestore", "btnSave"]);
			        //        util.Control.setVisible(app, true, ["btnUpdate", "btnDelete"]);
			        app.lookup("cmnMultifileupload").readOnly = true;
			        app.lookup("cmnMultifileupload2").readOnly = true;
			        app.lookup("cmnMultifileupload3").readOnly = true;
			    } else if (psType == "READ_ONLY") {
			        util.Control.setReadOnly(app, true, "grpBoardDtl");
			        
			        // editor 숨김처리 및 html 스니펫 출력
			        vcGrpCont.getLayout().setRowVisible(0, true);
			        vcGrpCont.getLayout().setRowVisible(1, false);
			        
			        app.lookup("grpBoardDtl").getLayout().setRowVisible(1, false);
			        app.lookup("grpBoardDtl").getLayout().setRowVisible(2, false);
			        
			        util.Control.setVisible(app, false, ["btnRestore", "btnSave"]);
			        //        util.Control.setVisible(app, false, ["btnUpdate", "btnDelete"]);
			        app.lookup("cmnMultifileupload").readOnly = true;
			        app.lookup("cmnMultifileupload2").readOnly = true;
			        app.lookup("cmnMultifileupload3").readOnly = true;
			    } else {
			        if (psType == "UPDATE") {
			            //var vcGrpDtail = app.lookup("grpDetail");
			            app.lookup("grpBoardDtl").getLayout().setRowVisible(1, false);
			            app.lookup("grpBoardDtl").getLayout().setRowVisible(2, true);
			            util.Control.setReadOnly(app, false, "grpDetail");
			            
			            var vcEditer = app.lookup("cmnHtmlEditor");
			            var vsSeltContVal = util.DataSet.getValue(app, "dsList", 0, "DOC_INO_CN");
			            
			            cpr.core.DeferredUpdateManager.INSTANCE.asyncExec(function() {
			                vcEditer.setValue(vsSeltContVal);
			            });
			            app.lookup("cmnMultifileupload").readOnly = false;
			            app.lookup("cmnMultifileupload2").readOnly = false;
			            app.lookup("cmnMultifileupload3").readOnly = false;
			        }
			        util.Control.setReadOnly(app, false, "grpBoardDtl");
			        
			        vcGrpCont.getLayout().setRowVisible(0, false);
			        vcGrpCont.getLayout().setRowVisible(1, true);
			        
			        //        util.Control.setVisible(app, false, ["btnUpdate", "btnDelete"]);
			        util.Control.setVisible(app, true, ["btnRestore", "btnSave"]);
			    }
			}

