			function doSave() {
			    var iobxCd = util.DataMap.getValue(app, "dmSave", "IOBX_SE_CD");
			    if (iobxCd == "O") {
			        var vcfld = app.lookup("cmnMultifileupload2");
			    } else {
			        var vcfld = app.lookup("cmnMultifileupload");
			    }
			    
			    util.DataMap.setValue(app, "dmSave", "ATFINO", vcfld.atfino);
			    
			    util.Submit.send(app, "subSave", function(pbSuccess) {
			        
			        if (pbSuccess) {
			            var hostApp = app.getHostAppInstance();
			            
			            if (hostApp.hasAppMethod("doList")) {
			                hostApp.callAppMethod("doList", "save");
			                app.lookup("dmSave").clear();
			                util.Control.redraw(app, "grpData");
			            }
			            
			            if (hostApp.hasAppMethod("selectMdiItem")) {
			                hostApp.callAppMethod("selectMdiItem", 1);
			            }
			            
			        }
			    });
			}

