			function docRcvrPopup() {
			    util.Dialog.open(app, "app/itgcms/wrksupt/docsr/DocRcvrUsrPopup", "주소록", 940, 760, function( /*cpr.events.CUIEvent*/ e) {
			        
			        /**@type cpr.controls.Dialog*/
			        var dialog = e.control;
			        var returnVal = dialog.returnValue;
			        
			        if (dialog.returnValue != null && dialog.returnValue.indexOf("|") > -1) {
			            var tmpArr = dialog.returnValue.split("^");
			            var vsInfo = "";
			            for (var i = 0; i < tmpArr.length; i++) {
			                
			                var datas = tmpArr[i].split("|");
			                var USER_ID = datas[0];
			                var FLNM = datas[1];
			                var SXDC_SE_CD = datas[2];
			                var MBL_TELNO = datas[3];
			                var EML_ADDR = datas[4];
			                var MSNGR_ID = datas[5];
			                var UNT_SYSTEM = datas[6];
			                var INST_NM = datas[7];
			                var MEMBER_TYPE = datas[8];
			                var MEMBER_NO = datas[9];
			                
			                var vsVal = USER_ID;
			                vsInfo += vsVal + ",";
			            }
			            vsInfo.slice(0, -1);
			            app.lookup("ipbTit2").value = vsInfo;
			        }
			    });
			    
			}

			function businessRcvrUsrPopup() {
			    util.Dialog.open(app, "app/itgcms/wrksupt/docsr/DocRcvrDsgn", "주소록", 940, 760, function( /*cpr.events.CUIEvent*/ e) {
			        
			        /**@type cpr.controls.Dialog*/
			        var dialog = e.control;
			        var returnVal = dialog.returnValue;
			        
			        if (!ValueUtil.isNull(returnVal)) {
			            var vsInfo = "";
			            
			            returnVal.forEach(function(val, idx) {
			                var vsVal = val["userId"];
			                vsInfo += vsVal + ",";
			            });
			            vsInfo.slice(0, -1);
			            app.lookup("ipbTit2").value = vsInfo;
			        }
			        
			    });
			}

